function findClosestNumber(nums) {
  let closest = nums[0];

  for (const num of nums) {
    const distance = Math.abs(num);
    const bestDistance = Math.abs(closest);
    if (distance < bestDistance) {
      closest = num;
    } else if (distance === bestDistance && num > closest) {
      closest = num;
    }
  }
  return closest;
}

