function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 8);
  const span = size === 'large' ? 100000 : 1 + Math.floor(rand() * 10);
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  // Often plant a mirrored pair so the tie rule matters.
  if (rand() < 0.5) {
    const k = Math.floor(rand() * span) + 1;
    nums[Math.floor(rand() * n)] = -k;
    nums[Math.floor(rand() * n)] = k;
  }
  return [nums];
}
